   )`,
  `CREATE INDEX IF NOT EXISTS webhook_deliveries_org_status_idx ON webhook_deliveries (org_id, status)`,
  `CREATE TABLE IF NOT EXISTS rate_limit_buckets (
     id TEXT PRIMARY KEY NOT NULL,
