import { z } from "zod";
import { issuePrioritySchema } from "./issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real `YYYY-MM-DD` calendar date (so `2026-02-30` is rejected). */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (!match) return false;
  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True for an IANA time zone name the runtime's `Intl` data knows. */
export function isKnownTimeZone(value: string): boolean {
  // Offset strings ("+01:00") are accepted by newer `Intl`, but are not IANA zones.
  if (value.length === 0 || /^[+-]/.test(value)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

export const recurrenceCadenceSchema = z.enum(["daily", "weekly"]);

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: recurrenceCadenceSchema,
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string().refine(isKnownTimeZone, "unknown time zone"),
    startsOn: z.string().refine(isCalendarDate, "must be a YYYY-MM-DD date"),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a weekly rule needs a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a daily rule has no weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;
export type ParsedCreateRecurringIssueInput = z.output<
  typeof createRecurringIssueSchema
>;
EOF
