/**
 * Files the latest due occurrence of every non-paused recurring issue rule as
 * an ordinary issue, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): can, createIssue, isArchived
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { createIssueSchema } from "@/schemas/issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import {
  isActiveMember,
  latestOccurrence,
} from "@/server/services/recurring-issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * One pass over every non-paused rule. Missed occurrences are never
 * back-filled: a rule files at most one issue per run, for its latest started
 * occurrence, and only when that is newer than `lastOccurrenceOn`.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if (await fileOccurrence(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Returns true when an issue was created for `rule`. */
async function fileOccurrence(rule: RecurringIssue, now: Date): Promise<boolean> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    logger.warn("recurring issue paused: creator may no longer file issues", {
      recurringIssueId: rule.id,
    });
    return false;
  }

  const assigneeId =
    rule.assigneeId !== null && (await isActiveMember(rule.orgId, rule.assigneeId))
      ? rule.assigneeId
      : null;

  await createIssue(
    actor,
    createIssueSchema.parse({
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      description: null,
      dueAt: null,
      labelIds: [],
    }),
  );

  await recurringIssueRepo.setLastOccurrence(rule.orgId, rule.id, occurrence);
  return true;
}
