/**
 * Recurring issue rules: authorization, the per-plan rule quota and the
 * occurrence arithmetic the recurring-issue job files issues from.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

/**
 * Creates a rule after the same gates as creating an issue in its project,
 * plus an active assignee and the plan's `recurringIssues` quota.
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (
    parsed.assigneeId !== null &&
    !(await isActiveMember(parsed.orgId, parsed.assigneeId))
  ) {
    throw new Error(
      `Assignee ${parsed.assigneeId} is not an active member of this organization`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringIssueRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(`Plan ${org.plan} allows no more recurring issues`);
  }

  return recurringIssueRepo.insertRecurringIssue(parsed, actor.userId);
}

export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringIssueRepo.findRecurringIssueById(
      input.orgId,
      input.recurringIssueId,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringIssueRepo.setRecurringIssuePaused(
    input.orgId,
    rule.id,
    input.paused,
  );
}

export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}

/** True when `userId` is a live, active member of `orgId`. */
export async function isActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.status === "active";
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** The `YYYY-MM-DD` calendar day `now` falls on in `timezone`. */
export function localDateIn(now: Date, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const part = (type: string) =>
    parts.find((candidate) => candidate.type === type)?.value ?? "";
  return `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
}

function toUtcDay(date: string): Date {
  const [year, month, day] = date.split("-").map(Number);
  return new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1));
}

function fromUtcDay(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/**
 * The latest occurrence of `rule` whose local day has started by `now`, or
 * `null` when none has. A day D has started once the wall clock in the rule's
 * time zone reaches 00:00 on D, i.e. once the local date is D or later.
 */
export function latestOccurrence(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  const today = localDateIn(now, rule.timezone);
  if (today < rule.startsOn) return null;
  if (rule.cadence === "daily") return today;

  const todayUtc = toUtcDay(today);
  const isoWeekday = todayUtc.getUTCDay() === 0 ? 7 : todayUtc.getUTCDay();
  const back = (isoWeekday - (rule.weekday ?? 1) + 7) % 7;
  const occurrence = fromUtcDay(new Date(todayUtc.getTime() - back * MS_PER_DAY));
  return occurrence < rule.startsOn ? null : occurrence;
}
